import heapq

def match(orders):
    trades = []
    buy_heap = []  # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    book = {}  # id -> [side, price, qty_remaining, seq]
    seq_counter = [0]

    def next_seq():
        seq_counter[0] += 1
        return seq_counter[0]

    def clean_buy_heap():
        while buy_heap:
            negprice, s, oid = buy_heap[0]
            if oid not in book or book[oid][2] <= 0:
                heapq.heappop(buy_heap)
            else:
                break

    def clean_sell_heap():
        while sell_heap:
            price, s, oid = sell_heap[0]
            if oid not in book or book[oid][2] <= 0:
                heapq.heappop(sell_heap)
            else:
                break

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            if oid in book:
                del book[oid]
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty

        if side == 'buy':
            while remaining > 0:
                clean_sell_heap()
                if not sell_heap:
                    break
                best_price, s, sell_id = sell_heap[0]
                if price is not None and best_price > price:
                    break
                sell_order = book[sell_id]
                trade_qty = min(remaining, sell_order[2])
                trades.append([oid, sell_id, best_price, trade_qty])
                remaining -= trade_qty
                sell_order[2] -= trade_qty
                if sell_order[2] <= 0:
                    del book[sell_id]
                    heapq.heappop(sell_heap)
            if typ == 'limit' and remaining > 0:
                s = next_seq()
                book[oid] = ['buy', price, remaining, s]
                heapq.heappush(buy_heap, (-price, s, oid))
        else:  # sell
            while remaining > 0:
                clean_buy_heap()
                if not buy_heap:
                    break
                negprice, s, buy_id = buy_heap[0]
                best_price = -negprice
                if price is not None and best_price < price:
                    break
                buy_order = book[buy_id]
                trade_qty = min(remaining, buy_order[2])
                trades.append([buy_id, oid, best_price, trade_qty])
                remaining -= trade_qty
                buy_order[2] -= trade_qty
                if buy_order[2] <= 0:
                    del book[buy_id]
                    heapq.heappop(buy_heap)
            if typ == 'limit' and remaining > 0:
                s = next_seq()
                book[oid] = ['sell', price, remaining, s]
                heapq.heappush(sell_heap, (price, s, oid))

    return trades

